pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(address(0xbad), 1 ether);
        vm.prank(address(0xbad));
        payable(address(c)).transfer(1 ether);

        uint256 balanceBefore = bob.balance;
        vm.prank(c.Owner());
        c.Command{value: 0}(bob, "");
        uint256 balanceAfter = bob.balance;

        assertTrue(balanceAfter - balanceBefore == 0);
    }
}
